#include "stdlib/stats/base/dists/cosine/bisect.h"
#include "stdlib/stats/base/dists/cosine/cdf.h"

static const double MAX_ITERATIONS = 1e4;
static const double TOLERANCE = 1e-12;

/**
* Bisection method to find quantile as there is no closed-form expression for the inverse of the CDF.
*
* @private
* @param p   input value
* @param mu  location parameter
* @param s   scale parameter
* @return    evaluated quantile function
*/
double stdlib_base_dists_cosine_bisect( const double p, const double mu, const double s ) {
	double a;
	double b;
	double c;
	double m;
	double n;

	n = 1;
	a = mu - s;
	b = mu + s;
	m = ( a + b ) / 2.0;
	while ( n < MAX_ITERATIONS ) {
		m = ( a + b ) / 2.0;
		if ( b - a < TOLERANCE ) {
			return m;
		}
		c = stdlib_base_dists_cosine_cdf( m, mu, s );
		if ( p > c ) {
			a = m;
		} else {
			b = m;
		}
		n += 1;
	}
	return m;
}
